/*
    EMORA 07-10-2026 Retira Peligroso de productos temporalmente clasificados
    como Refrigerado o Ambiente, según DetallePesoProductosPeligrosos.xlsm.
*/
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @UsuarioId INT = 10001;
DECLARE @AtributosReactivados INT = 0;
DECLARE @AtributosCreados INT = 0;
DECLARE @PeligrososEliminados INT = 0;
DECLARE @Refrigerados VARCHAR(MAX) = '100201-VS,105-002166-00,105-004208-00,105-004209-00,105-004210-00,105-004211-00,105-004212-00,105-004213-00,105-004214-00,105-004215-00,105-004216-00,105-004217-00,105-004218-00,105-004219-00,105-004220-00,105-004221-00,105-004222-00,105-004223-00,105-004224-00,105-004225-00,105-004227-00,105-004228-00,105-004236-00,105-004237-00,105-004238-00,105-004239-00,105-004247-00,105-004248-00,105-004251-00,105-004276-00,105-004277-00,105-004278-00,105-004279-00,105-004280-00,105-004281-00,105-004282-00,105-004283-00,105-004284-00,105-004286-00,105-004287-00,105-004288-00,105-004289-00,105-004290-00,105-004291-00,105-004292-00,105-004293-00,105-004294-00,105-004296-00,105-004513-00,105-004515-00,105-004516-00,105-004605-00,105-004612-00,105-004628-00,105-005181-00,105-005182-00,105-005659-00,105-005664-00,105-005666-00,105-005672-00,105-005673-00,105-005674-00,105-005675-00,105-005738-00,105-005910-00,105-005914-00,105-005915-00,105-005916-00,105-005917-00,105-005923-00,105-005924-00,105-005925-00,105-005926-00,105-005931-00,105-005932-00,105-005935-00,105-005941-00,105-005942-00,105-005943-00,105-005944-00,105-006063-00,105-007379-00,105-007380-00,105-007381-00,105-007382-00,105-008549-00,105-008551-00,105-008552-00,105-008554-00,105-008555-00,105-008684-00,105-008890-00,105-008891-00,105-009169-00,105-009170-00,105-010219-00,105-010248-00,105-010258-00,105-010703-00,105-027044-00,105-028988-00,105-031858-00,105-031868-00,105-031870-00,105-035649-00,105-035738-00,105-045516-00,1300036418,130201005M,130205002M,225-LKF41,239DRI,240-284,241DRI,243DRI,247-210,247-220,250-110,275005,275539,311DRI,37DRI,ALP0102,ALP0103,ALP1104,AMY0102,AMY0103,AMY0104,AU448468,B1012-30B,B1015-15,BR-00106,C30103,C30104,C40103,C40104,CA0102,CA0103,CHE0102,CK0103,CK0103/2,CK1104,CKB0103,CKB0104,CRE0203,CRE1202,CRP0103,FE0103,GLU0102,GLU0104,HDL0103,HDL1104,IGA0104,IGG0104,IGM0104,LDH0102,LDH1104,MAD-003935M-H-HS24-24,MSADA181,RQ9135,TG0102,TG0104,UA0102,UA0103,UA0104';

DECLARE @ProductosObjetivo TABLE (Codigo VARCHAR(50) NOT NULL PRIMARY KEY, TATR_Id INT NOT NULL);
INSERT @ProductosObjetivo (Codigo, TATR_Id) SELECT TRIM(value), 4037 FROM STRING_SPLIT(@Refrigerados, ',');
INSERT @ProductosObjetivo (Codigo, TATR_Id) VALUES ('10634644', 4038), ('367364', 4038), ('442023', 4038), ('362788', 4038);

IF EXISTS (SELECT 1 FROM @ProductosObjetivo D LEFT JOIN dbo.PRO_Producto P ON P.PRO_Codigo = D.Codigo WHERE P.PRO_Id IS NULL)
    THROW 50001, 'Existen códigos del adjunto que no están creados en PRO_Producto.', 1;

BEGIN TRY
    BEGIN TRANSACTION;
    UPDATE PA SET PA.PROATR_Activo = 1, PA.PROATR_ModificadoPor = @UsuarioId, PA.PROATR_FechaModificacion = GETDATE()
    FROM dbo.PROATR_ProductoAtributo PA INNER JOIN dbo.PRO_Producto P ON P.PRO_Id = PA.PRO_Id INNER JOIN @ProductosObjetivo D ON D.Codigo = P.PRO_Codigo AND D.TATR_Id = PA.TATR_Id
    WHERE PA.PROATR_Activo = 0;
    SET @AtributosReactivados = @@ROWCOUNT;
    INSERT dbo.PROATR_ProductoAtributo (PRO_Id, TATR_Id, PROATR_ValorAtributo, PROATR_CreadoPor, PROATR_FechaCreacion, PROATR_Activo)
    SELECT P.PRO_Id, D.TATR_Id, '', @UsuarioId, GETDATE(), 1 FROM dbo.PRO_Producto P INNER JOIN @ProductosObjetivo D ON D.Codigo = P.PRO_Codigo
    WHERE NOT EXISTS (SELECT 1 FROM dbo.PROATR_ProductoAtributo PA WHERE PA.PRO_Id = P.PRO_Id AND PA.TATR_Id = D.TATR_Id);
    SET @AtributosCreados = @@ROWCOUNT;
    DELETE PA FROM dbo.PROATR_ProductoAtributo PA INNER JOIN dbo.PRO_Producto P ON P.PRO_Id = PA.PRO_Id INNER JOIN @ProductosObjetivo D ON D.Codigo = P.PRO_Codigo WHERE PA.TATR_Id = 4039;
    SET @PeligrososEliminados = @@ROWCOUNT;
    COMMIT TRANSACTION;
    SELECT @AtributosReactivados AS AtributosReactivados, @AtributosCreados AS AtributosCreados, @PeligrososEliminados AS PeligrososEliminados;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO
